const changedFiles = $json.changedFiles || [];
const commitMessage = ($json.commitMessage || "").toLowerCase();
const joined = changedFiles.join(" ").toLowerCase();

const hasRust =
  joined.includes("src-tauri") ||
  changedFiles.some(f => f.endsWith(".rs"));

const hasDb =
  joined.includes("migration") ||
  joined.includes("schema") ||
  changedFiles.some(f => f.endsWith(".sql"));

const hasUi = changedFiles.some(f =>
  f.endsWith(".tsx") ||
  f.endsWith(".jsx") ||
  f.endsWith(".ts") ||
  f.endsWith(".js")
);

const hasSecurity =
  joined.includes("auth") ||
  joined.includes("permission") ||
  joined.includes("token") ||
  joined.includes("secret") ||
  joined.includes("session");

const hasPharmacyLogic =
  joined.includes("inventory") ||
  joined.includes("stock") ||
  joined.includes("expiry") ||
  joined.includes("prescription") ||
  joined.includes("invoice") ||
  joined.includes("payment") ||
  joined.includes("sync");

const docsOnly =
  changedFiles.length > 0 &&
  changedFiles.every(f =>
    f.endsWith(".md") ||
    f.startsWith("docs/") ||
    f.startsWith(".ai/")
  );

let risk = "low";
const domains = [];

if (docsOnly) {
  risk = "low";
  domains.push("docs");
}

if (hasUi && !hasRust && !hasDb && !hasSecurity && !hasPharmacyLogic) {
  risk = "medium";
  domains.push("ui");
}

if (hasRust) domains.push("rust");
if (hasDb) domains.push("database");
if (hasPharmacyLogic) domains.push("pharmacy_logic");

if (hasRust || hasDb || hasPharmacyLogic) {
  risk = "high";
}

if (hasSecurity) {
  risk = "critical";
  domains.push("security");
}

return [
  {
    json: {
      ...$json,
      taskClassification: {
        risk,
        domains,
        changedFiles,
        commitMessage
      }
    }
  }
];

const usage = $json.usageState || {
  windsurf: {
    dailyRemainingPercent: 100,
    weeklyRemainingPercent: 38
  }
};

const windsurf = usage.windsurf || {};
const weekly = Number(windsurf.weeklyRemainingPercent ?? 100);
const daily = Number(windsurf.dailyRemainingPercent ?? 100);

let quotaMode = "fast";

if (weekly < 20 || daily < 15) {
  quotaMode = "emergency";
} else if (weekly < 40 || daily < 30) {
  quotaMode = "conservation";
} else if (weekly < 70) {
  quotaMode = "normal";
}

const classification = $json.taskClassification || {};
const risk = classification.risk || "low";
const domains = classification.domains || [];

const isLogicHeavy =
  domains.includes("rust") ||
  domains.includes("database") ||
  domains.includes("pharmacy_logic");

const isCritical =
  risk === "critical" ||
  domains.includes("security");

let route = {
  quotaMode,
  primaryAgent: "windsurf-cascade",
  primaryModel: "sonnet-4.6",
  fallbackAgent: "github-copilot",
  reviewAgent: null,
  architectureAgent: null,
  allowAutoEdit: true,
  requiresHumanApproval: false
};

if (risk === "low") {
  route.primaryAgent = "github-copilot";
  route.primaryModel = "fast-available-copilot-model";
  route.allowAutoEdit = true;
}

if (risk === "medium") {
  route.primaryAgent = quotaMode === "emergency" ? "github-copilot" : "windsurf-cascade";
  route.primaryModel = quotaMode === "emergency" ? "copilot-strong-available-model" : "sonnet-4.6";
  route.allowAutoEdit = quotaMode !== "emergency";
}

if (risk === "high" || isLogicHeavy) {
  route.primaryAgent = "openrouter-deepseek-review";
  route.primaryModel = "deepseek/deepseek-v4";
  route.reviewAgent = "deepseek";
  route.architectureAgent = "gemini-ultra";
  route.allowAutoEdit = false;
  route.requiresHumanApproval = true;
}

if (isCritical) {
  route.primaryAgent = "gpt-5.5-security-review";
  route.primaryModel = "openai/gpt-5.5";
  route.reviewAgent = "gpt-5.5";
  route.architectureAgent = "gemini-ultra";
  route.allowAutoEdit = false;
  route.requiresHumanApproval = true;
}

return [
  {
    json: {
      ...$json,
      quotaRoute: route
    }
  }
];
